import base64

binary_data = ""

decoded_bytes = bytes(int(binary_data[i:i+8], 2) for i in range(0, len(binary_data), 8))
ascii_text = decoded_bytes.decode()

hex_data = base64.b32decode(ascii_text)

base64_data = bytes.fromhex(hex_data.decode())

flag = base64.b64decode(base64_data).decode()

print(flag)
